int snd_usb_midi_create(struct snd_card *card, struct usb_interface *iface,
                        struct list_head *midi_list,
                        const struct snd_usb_audio_quirk *quirk)
{
        struct snd_usb_midi *midi;
        int err;

        midi = kzalloc(sizeof(*midi), GFP_KERNEL);
        if (!midi)
                return -ENOMEM;

        midi->iface = iface;
        midi->card = card;
        usb_set_intfdata(iface, midi);

        err = snd_usb_midi_detect_endpoints(midi, quirk);
        if (err < 0)
                goto error;

        err = snd_usb_midi_input_init(midi);
        if (err < 0)
                goto error;

        err = snd_usb_midi_output_init(midi);
        if (err < 0)
                goto error;

        err = snd_rawmidi_new(card, "USB MIDI", -1, midi->ports, 0, &midi->rmidi);
        if (err < 0)
                goto error;

        snprintf(card->driver, sizeof(card->driver), "USB-MIDI");
        snd_rawmidi_set_ops(midi->rmidi, SNDRV_RAWMIDI_STREAM_OUTPUT, &snd_usb_midi_output);
        snd_rawmidi_set_ops(midi->rmidi, SNDRV_RAWMIDI_STREAM_INPUT, &snd_usb_midi_input);
        midi->rmidi->info = SNDRV_RAWMIDI_INFO_OUTPUT | SNDRV_RAWMIDI_INFO_INPUT |
                            SNDRV_RAWMIDI_INFO_DUPLEX;

        list_add(&midi->list, midi_list);
        return 0;

error:
        snd_usb_midi_delete(midi);
        return err;
}

int snd_usb_midi_create(struct snd_card *card, struct usb_interface *iface,
                        struct list_head *midi_list,
                        const struct snd_usb_audio_quirk *quirk)
{
        struct snd_usb_midi *midi;
        int err;

        midi = kzalloc(sizeof(*midi), GFP_KERNEL);
        if (!midi)
                return -ENOMEM;

        midi->chip.card = card;
        midi->iface = iface;
        usb_set_intfdata(iface, &midi->chip);

        err = snd_usb_midi_detect_endpoints(midi, quirk);
        if (err < 0)
                goto error;

        err = snd_rawmidi_new(card, "USB MIDI", -1, 1, 1, &midi->rmidi);
        if (err < 0)
                goto error;

        midi->rmidi->private_data = &midi->chip;
        strcpy(midi->rmidi->name, "USB MIDI");

        list_add(&midi->list, midi_list);
        return 0;

error:
        kfree(midi);
        return err;
}

